import { APPS } from './shared/apps.js';
import { getConfig, setConfig, persist } from './shared/store.js';
import { THEMES, DATE_FORMATS, loadPrefs, setPref, applyTheme } from './shared/prefs.js';
import { testConnection, pull, write, drain } from './shared/github.js';
import { createSync } from './shared/sync.js';
import { serialize } from './shared/md.js';

const $ = s => document.querySelector(s);
const show = id => document.querySelectorAll('section').forEach(s => s.hidden = s.id !== id);

// The same sequence every screen in Mine runs, and for the same reason: the queue is shared, so
// whichever screen is open is the one that has to push what the other one left behind. This
// screen has no model to reload and no logs panel to send you to, so it takes neither.
const sync = createSync({ line: $('#status') });

// ---- setup ----

$('#setup-form').addEventListener('submit', async e => {
  e.preventDefault();
  const btn = e.target.querySelector('button');
  const msg = $('#setup-msg');
  const cfg = Object.fromEntries(new FormData(e.target));
  btn.disabled = true;
  msg.className = 'msg';
  msg.textContent = 'Checking…';
  try {
    const info = await testConnection(cfg);
    await setConfig(cfg);
    await persist();
    msg.textContent = info.private ? '' : 'Note: that repo is public.';
    await home();
  } catch (err) {
    msg.textContent = err.message;
    msg.className = 'msg bad';
  } finally {
    btn.disabled = false;
  }
});

// ---- home ----

async function home() {
  const cfg = await getConfig();

  $('#tiles').replaceChildren(...APPS.map(a => {
    const link = document.createElement('a');
    link.className = 'tile';
    link.href = `./${a.slug}/`;
    const img = document.createElement('img');
    img.src = `./${a.slug}/icon.svg`;
    img.alt = '';
    const name = document.createElement('span');
    name.textContent = a.label;
    link.append(img, name);
    return link;
  }));

  const days = cfg.expiresAt ? Math.ceil((new Date(cfg.expiresAt) - Date.now()) / 86400000) : null;
  const expiry = $('#expiry');
  expiry.hidden = days === null || days > 14;
  if (!expiry.hidden) {
    expiry.textContent = days <= 0
      ? 'Your token has expired. Replace it in settings.'
      : `Your token expires in ${days} day(s). Replace it in settings.`;
  }

  show('home');
  await sync.refresh();
}

addEventListener('focus', () => { if (!$('#home').hidden) sync.refresh(); });

// ---- settings ----

$('#to-settings').addEventListener('click', async () => {
  const cfg = await getConfig();
  $('#settings-info').replaceChildren(...Object.entries({
    Repo: `${cfg.owner}/${cfg.repo}`,
    Branch: cfg.branch,
    Token: `on this device only${cfg.expiresAt ? `, expires ${cfg.expiresAt}` : ''}`
  }).flatMap(([k, v]) => {
    const dt = document.createElement('dt');
    const dd = document.createElement('dd');
    dt.textContent = k;
    dd.textContent = v;
    return [dt, dd];
  }));
  $('#steps').replaceChildren();
  await minePrefs();
  show('settings');
});

$('#to-home').addEventListener('click', home);

// Theme and date format belong to Mine rather than to any one app, so the same two rows appear
// here and in every app's settings.
async function minePrefs() {
  const prefs = await loadPrefs();
  $('#mine-prefs').replaceChildren(
    prefRow('Theme', THEMES, prefs.theme, 'theme'),
    prefRow('Date format', DATE_FORMATS, prefs.dateFormat, 'dateFormat'),
    row('p', 'note', 'Both apply to all of Mine. They follow the device until you choose otherwise.')
  );
}

const row = (tag, cls, text) => {
  const n = document.createElement(tag);
  n.className = cls;
  n.textContent = text;
  return n;
};

function prefRow(label, options, current, key) {
  const wrap = row('div', 'prefrow', '');
  const select = document.createElement('select');
  for (const v of options) {
    const o = document.createElement('option');
    o.value = v;
    o.textContent = v;
    o.selected = v === current;
    select.append(o);
  }
  select.addEventListener('change', async () => {
    await setPref(key, select.value);
    if (key === 'theme') applyTheme(select.value);
  });
  wrap.append(row('span', '', label), select);
  return wrap;
}

$('#forget').addEventListener('click', () => {
  if (!confirm('Remove the repo settings and token from this device? Your data in GitHub is untouched.')) return;
  indexedDB.deleteDatabase('mine');
  location.reload();
});

// Proves the architecture against the real repo: GraphQL read, atomic write, pull back.
$('#verify').addEventListener('click', async () => {
  const list = $('#steps');
  list.replaceChildren();
  const add = text => {
    const li = document.createElement('li');
    li.textContent = text;
    list.append(li);
    return li;
  };
  const run = async (text, fn) => {
    const li = add(`${text} …`);
    try {
      li.textContent = `${text} — ${await fn()}`;
      li.className = 'done';
    } catch (err) {
      li.textContent = `${text} — failed: ${err.message}`;
      li.className = 'bad';
      throw err;
    }
  };

  try {
    await run('Read repo', async () => {
      const i = await testConnection(await getConfig());
      return `${i.name}, ${i.private ? 'private' : 'PUBLIC'}`;
    });
    await run('Write README.md, one commit', async () => {
      await write('README.md', serialize(
        { title: 'Mine data', verified: new Date().toISOString() },
        'Markdown written by Mine. Safe to edit by hand.'));
      return `commit ${(await drain('Verify round-trip from Mine')).commit.slice(0, 7)}`;
    });
    await run('Pull it back', async () => `${(await pull()).changed} file(s) reconciled`);
    add('Round-trip complete').className = 'done';
  } catch {
    /* the failing step already says why */
  }
});

// ---- service worker ----

// Ask a worker for its VERSION. An older worker that predates the version message answers
// nothing, and the timeout reports that as null.
function versionOf(worker) {
  return new Promise(resolve => {
    if (!worker) return resolve(null);
    const ch = new MessageChannel();
    const timer = setTimeout(() => resolve(null), 1500);
    ch.port1.onmessage = e => { clearTimeout(timer); resolve(e.data); };
    try { worker.postMessage('version', [ch.port2]); }
    catch { clearTimeout(timer); resolve(null); }
  });
}

// Skip-waiting, then reload once the new worker has taken over.
function takeOver(worker) {
  navigator.serviceWorker.addEventListener('controllerchange',
    () => location.reload(), { once: true });
  worker.postMessage('skip-waiting');
}

// The way to the newest version that does not depend on the banner being there. A plain reload
// would leave a waiting worker waiting, so look for one first and hand over to it.
$('#reload-app').addEventListener('click', async () => {
  const reg = await navigator.serviceWorker?.getRegistration();
  // Offline there is nothing to fetch, and the reload still happens.
  await reg?.update().catch(() => {});
  const w = reg?.installing;
  if (w) await new Promise(done => w.addEventListener('statechange', done, { once: true }));
  if (reg?.waiting) takeOver(reg.waiting);
  else location.reload();
});

function registerSW() {
  if (!navigator.serviceWorker) return;
  navigator.serviceWorker.register('./sw.js', { type: 'module', scope: './' }).then(reg => {
    // "A worker is waiting" is not the test: a byte-identical worker can wait, and the banner
    // would then show on an app with no update at all and never go away. Offer it only when the
    // version waiting to take over genuinely differs from the one running.
    const offer = async () => {
      if (!reg.waiting || !navigator.serviceWorker.controller) return;
      const [waiting, active] = await Promise.all([versionOf(reg.waiting), versionOf(reg.active)]);
      if (waiting !== active) $('#update').hidden = false;
    };
    offer();
    reg.addEventListener('updatefound', () => {
      const w = reg.installing;
      w?.addEventListener('statechange', () => { if (w.state === 'installed') offer(); });
    });
    $('#reload').addEventListener('click', () => { if (reg.waiting) takeOver(reg.waiting); });
  }).catch(() => { /* an app that cannot cache still works online */ });
}

// ---- boot ----

registerSW();
applyTheme((await loadPrefs()).theme);
if (await getConfig()) await home(); else show('setup');
// One IndexedDB for all apps. Same origin across /mine/ and /mine/<app>/, so the settings
// written by the main app are readable from every subfolder. Verified on iOS and Android.
const NAME = 'mine', VERSION = 1;
let opening;

function db() {
  return opening ||= new Promise((res, rej) => {
    const r = indexedDB.open(NAME, VERSION);
    r.onupgradeneeded = () => {
      const d = r.result;
      d.createObjectStore('kv');                             // config, sync metadata
      d.createObjectStore('files', { keyPath: 'path' });     // { path, text, oid }
      d.createObjectStore('queue', { autoIncrement: true }); // pending writes
    };
    r.onsuccess = () => res(r.result);
    r.onerror = () => rej(r.error);
  });
}

async function run(store, mode, fn) {
  const d = await db();
  return new Promise((res, rej) => {
    const t = d.transaction(store, mode), q = fn(t.objectStore(store));
    t.onerror = () => rej(t.error);
    if (q) { q.onsuccess = () => res(q.result); q.onerror = () => rej(q.error); }
    else t.oncomplete = () => res();
  });
}

export const getKV = k => run('kv', 'readonly', s => s.get(k));
export const setKV = (k, v) => run('kv', 'readwrite', s => s.put(v, k));

export const getConfig = () => getKV('config');
export const setConfig = c => setKV('config', c);

export const getFile = path => run('files', 'readonly', s => s.get(path));
export const putFile = f => run('files', 'readwrite', s => s.put(f));
export const delFile = path => run('files', 'readwrite', s => s.delete(path));
export const allFiles = async prefix =>
  (await run('files', 'readonly', s => s.getAll()))
    .filter(f => !prefix || f.path.startsWith(prefix));

export const enqueue = item => run('queue', 'readwrite', s => s.add(item));
export const queuedCount = () => run('queue', 'readonly', s => s.count());

// Each item with the key it is stored under, both read in one transaction: a drain removes the
// items it actually read, by key, and a write that landed while it was running must still be
// there afterwards. Two separate reads could not be trusted to line up - an `add` between them
// would lengthen one list and not the other. Within the one transaction they do line up by
// index, because both are defined to walk the records in ascending key order.
export async function queued() {
  const d = await db();
  return new Promise((res, rej) => {
    const t = d.transaction('queue', 'readonly'), s = t.objectStore('queue');
    const keys = s.getAllKeys(), items = s.getAll();
    t.onerror = () => rej(t.error);
    t.oncomplete = () => res(items.result.map((item, i) => ({ ...item, key: keys.result[i] })));
  });
}

export const dequeue = keys =>
  run('queue', 'readwrite', s => { for (const k of keys) s.delete(k); });

// Request persistent storage. Granted without a prompt in an installed app on both
// iOS and Android; without it, iOS evicts storage after ~7 days idle.
export async function persist() {
  try { return await navigator.storage.persisted() || await navigator.storage.persist(); }
  catch { return false; }
}
import yaml from './vendor/js-yaml.mjs';

const FM = /^---\r?\n([\s\S]*?)\r?\n---\r?\n?/;

// CORE_SCHEMA, never DEFAULT: the default schema parses `start: 2026-04-18` into a JS Date
// at UTC midnight, which is the all-day off-by-one-day bug the format exists to avoid.
export function parse(text) {
  const m = text.match(FM);
  if (!m) return { data: {}, body: text };
  return {
    data: yaml.load(m[1], { schema: yaml.CORE_SCHEMA }) || {},
    body: text.slice(m[0].length)
  };
}

export function serialize(data, body = '') {
  const lines = [];
  for (const [k, v] of Object.entries(data)) {
    if (v === undefined || v === null || v === '') continue;   // omit, never "None"
    if (Array.isArray(v)) {
      if (!v.length) continue;
      lines.push(`${k}:`, ...v.map(i => `  - ${scalar(i)}`));
    } else {
      lines.push(`${k}: ${scalar(v)}`);
    }
  }
  return `---\n${lines.join('\n')}\n---\n\n${body.replace(/^\n+/, '')}`;
}

const PLAIN = /^[A-Za-z0-9][A-Za-z0-9 _.:+/@-]*$/;
const LOOKS_TYPED = /^(true|false|null|~|-?\d+(\.\d+)?)$/i;

function scalar(v) {
  if (typeof v === 'boolean' || typeof v === 'number') return String(v);
  const s = String(v);
  const safe = PLAIN.test(s) && !/: |\s$/.test(s) && !LOOKS_TYPED.test(s);
  return safe ? s : JSON.stringify(s);   // valid YAML double-quoted scalar
}
// The sync line and the logs panel, for every app in Mine.
//
// Both apps had their own copy of the same sequence - drain the queue, then pull, and say on one
// line what happened - and only the calendar had the panel that explains it. The sequence is not
// either app's: the queue and the mirror are shared, so whichever screen is open is the one that
// has to push what the other one left behind.
//
// Two rules are built in here rather than left to each caller to remember:
//
//   * One attempt at a time. The queue is shared, and two drains over it would build two commits
//     out of the same items.
//   * A queue is drained first and the pull waits for it, and runs only if the drain got through.
//     Whatever fails a drain - the token, the network - fails a pull too, and pulling over a
//     dirty queue rewrites the mirror underneath the changes still in it.
import { queuedCount, queued } from './store.js';
import { drain, pull, lastSync, discardQueue } from './github.js';
import { el, row } from './ui.js';

// `line` is the element that reports: a paragraph on the tile screen, a button on an app screen.
