export function plain(md) {
  return String(md)
    .replace(/```[^\n]*\n?/g, '')                         // fence lines; the code itself stays
    .replace(/!?\[([^\]]*)\]\([^)]*\)/g, '$1')            // a link or an image: its words
    .replace(/<[^>]+>/g, ' ')
    .replace(/^[ \t]*(#{1,6}|>|[-*+]|\d+[.)])[ \t]+(\[[ xX]\][ \t]+)?/gm, '')
    .replace(/[*~`]+/g, '')
    .replace(/(^|[^\p{L}\p{N}])_+|_+(?=[^\p{L}\p{N}]|$)/gu, '$1')   // not the _ in snake_case
