/* Calendar. Phone first: the desktop grid is the enhancement, not the other way round. Every
   view shows seven columns beginning with the configured first day of the week, and a month
   cell carries titled lines rather than dots - a Saturday task has to be readable.

   Loaded after ../style.css, which carries everything shared with the other apps: the tokens,
   the form primitives, the icon button, the three overlay mechanisms, the settings row, the
   logs panel and a rendered markdown body. Only what is the calendar's own is in here. */

/* Today is the one accent, so it is the one the whole of Mine already names. The three stages
   are the calendar's own and are declared here for every theme: ui.js hands them out as
   `var(--todo)` rather than as hexes, because a stage has to hold on paper and at night. */
:root {
  --cell: 3.3rem; --hour: 2.4rem; --gutter: 2rem; --tcol: 3rem;
  --today: var(--link);
  --todo: #9c4a35; --doing: #a9792a; --done: #4f6b3f;
}
@media (prefers-color-scheme: dark) {
  :root:not([data-theme="light"]) { --todo: #f08a7a; --doing: #eac46a; --done: #8fd0a0; }
}
:root[data-theme="dark"] { --todo: #f08a7a; --doing: #eac46a; --done: #8fd0a0; }
:root[data-theme="coffee"] { --todo: #f27a6a; --doing: #f0c05a; --done: #9fd07f; }
:root[data-theme="neutral"] { --todo: #9c4a35; --doing: #a9792a; --done: #4f6b3f; }

body { padding-bottom: env(safe-area-inset-bottom); }
#cal { display: flex; flex-direction: column; min-height: 100vh; min-height: 100dvh; }

/* The pane docked at the bottom: it sticks there, the sync line takes the top, and the home
   indicator's inset is the pane's to keep clear rather than the page's. */
body.dock-bottom { padding-bottom: 0; }
.dock-bottom .topbar {

/* ---- top pane ---- */
/* Three groups: the two view controls left, the period centred, the two ways out right. The
   centre is centred on the pane rather than on what is left over, which is what the two equal
   side tracks buy. Everything in it is drawn at twice the size it was - this is the row reached
   for on every visit, and it was the smallest thing on the screen. */
.topbar {
  position: sticky; top: 0; z-index: 5;
  display: grid; grid-template-columns: 1fr auto 1fr; align-items: center; gap: .3rem;
  padding: max(.5rem, env(safe-area-inset-top)) .5rem .5rem;
  background: var(--bg); border-bottom: 1px solid var(--line);
}
/* Nothing in the pane is filled: the four errand buttons are outlined and the two that step the
   period carry nothing at all, so the row is hairlines and the label, and the label is the
   heaviest thing in it. A filled block either side of it was the loudest thing on the page. */
.topbar .nav.ic { background: none; border: 1px solid var(--line); }
.topbar .nav.ic:hover, .tb-mid .nav:hover { background: var(--soft); }
.tb-mid .nav { background: none; }
.tb-mid .nav:active { background: var(--line); }
.tb-side { display: flex; align-items: center; gap: .3rem; min-width: 0; }
.tb-side.end { justify-content: flex-end; }
.tb-mid { display: flex; align-items: center; gap: .1rem; min-width: 0; }
/* The period label is a button with nothing drawn on it, so hover and press are what say it is
   one - the same affordance the year view's month caption uses. */
.period:hover { background: var(--soft); }
.period:active { background: var(--line); }
.nav {
  display: inline-flex; align-items: center; justify-content: center;
  width: auto; min-width: 2.6rem; min-height: 2.6rem; margin: 0; padding: .3rem .45rem;
  font-size: 2rem; line-height: 1; font-weight: 500; text-decoration: none;
  color: var(--fg); background: var(--soft); border: 0; border-radius: .55rem;
}
.nav.ic svg { width: 1.8rem; height: 1.8rem; display: block; }
/* The zoom in a calendar view reads the period it is in rather than drawing an icon. */
.nav.ic .glyph { font-size: 1.5rem; font-weight: 700; line-height: 1; min-width: 1.8rem; }

/* A week or sprint label is long - "Sprint 7 - 02.11.2026 - 15.11.2026" is wider than a narrow
   phone on its own - so the label shrinks and ellipsises rather than pushing the page sideways.
   The dropdown still shows the period in full. */
.period {
  display: inline-flex; align-items: center; justify-content: center; min-width: 0;
  width: auto; margin: 0; padding: .4rem .4rem;
  font-family: var(--serif); font-size: 1.55rem; font-weight: 600; letter-spacing: -.008em;
  color: var(--fg); background: none; border: 0; border-radius: .5rem;
  white-space: nowrap; cursor: pointer;
}
#period-label { overflow: hidden; text-overflow: ellipsis; }

.view { flex: 1; min-height: 0; }
/* The line reports and is pressed. Nothing is drawn on it, so hover and press are what say it
   is a button - the same affordance the period label uses. `.bad` needs the second class to beat
   this rule's own colour, which the plain `.bad` in the Mine stylesheet is now behind. */
.sync {
  width: 100%; padding: .4rem .7rem; margin: 0; font: inherit; font-size: .75rem;
  text-align: left; color: inherit; background: none; border: 0; border-radius: .4rem;
  cursor: pointer;
}
.sync:hover { background: var(--soft); }
.sync:active { background: var(--line); }
.sync.bad { color: var(--bad); }

/* ---- month ---- */
.weekhead {
  display: grid; grid-template-columns: repeat(7, 1fr);
  padding: .35rem .25rem 0; font-size: .7rem; font-weight: 600;
  color: var(--muted); text-align: center; text-transform: uppercase; letter-spacing: .04em;
}
  .grid .eline .when { display: none; }
  #day-pop { max-height: 80dvh; }
  /* Two rows on a phone, each filling the width. Five controls across one line left the period
     label - the one thing in the pane you read rather than aim at - no wider than the buttons
     beside it, and the arrows that step it had to be dropped to make even that fit. A second
     row buys back both: the four that go somewhere share the first, the period takes the
     second. Wrapping does it, so the pane keeps one DOM order at every width - `order` puts
     the two side groups first and gives the middle a row of its own. */
  .topbar { display: flex; flex-wrap: wrap; gap: .15rem .1rem; padding-inline: .35rem; }
  .tb-side { flex: 1 1 0; order: 1; }
  .tb-side.end { order: 2; }
  .tb-side .nav { flex: 1; min-width: 0; padding: .3rem .1rem; }
  /* The second row. The arrows take one share each and the label three, so the two are equal
     in size and the label between them is larger - the label carries a date to be read and an
     arrow carries only a direction. */
  .tb-mid { flex: 0 0 100%; order: 3; gap: .15rem; }
  /* Docked at the bottom the period row goes on top, so the six buttons are nearest the thumb. */
  .dock-bottom .tb-mid { order: 0; }
  .tb-mid .nav { flex: 1 1 0; min-width: 0; }
  .nav { min-width: 2.2rem; }
  .nav.ic svg { width: clamp(1.3rem, 5.2vw, 1.9rem); height: clamp(1.3rem, 5.2vw, 1.9rem); }
  .nav.ic .glyph { font-size: clamp(1.1rem, 4.6vw, 1.6rem); min-width: 0; }
  /* The second row's arrows are drawn at the size of the icons on the row above: they were
     larger than everything over them, which made the row that steps the period the loudest
     thing in the pane. */
  .tb-mid .nav { font-size: clamp(1.3rem, 5.2vw, 1.9rem); }
  .period { flex: 3 1 0; padding: .3rem .1rem; font-size: clamp(1.25rem, 7vw, 2rem); }

  /* The board's pager fills the header: it is the only way to see another stage, and a small
     square in the middle of an otherwise empty row asked a thumb to aim at the narrowest part
     of it. The left track that balances the `+` on a desktop is dropped to make the room. */
.grow { display: flex; align-items: center; gap: .5rem; padding: .25rem 0; }
.gname { flex: 1; font-size: .88rem; }
.grow .gpick { flex: 1; width: auto; }
.grow input { flex: 1; margin: 0; padding: .45rem; }
.grow input[type="color"] { flex: none; width: 2.2rem; height: 2.1rem; padding: 0; }

/* ---- desktop ---- */
@media (min-width: 600px) {
  :root { --cell: 6.4rem; --gutter: 2.4rem; --tcol: 3.4rem; --hour: 2.8rem; }
  /* No cap on #cal: the pane, the calendar window and the sync line are as wide as the browser.
     The cap is on the board alone, below, so the pane cannot change width when the view does. */
  .topbar { padding: .7rem .8rem; gap: .5rem; }
  .dock-bottom .topbar { padding-top: .7rem; padding-bottom: max(.7rem, env(safe-area-inset-bottom)); }
  /* About half an arrow glyph either side of the label. Three controls crammed together read as
     one control, and this is the group the pane is used through. */
  .tb-mid { gap: 1rem; }
  .period { font-size: 1.9rem; }
  .nav.ic svg { width: 2.1rem; height: 2.1rem; }
  .nav.ic .glyph { font-size: 1.7rem; min-width: 2.1rem; }
  .nav { min-width: 3rem; min-height: 3rem; }
  .weekhead { font-size: .75rem; padding: .5rem .3rem .2rem; }
  .day { padding: .22rem; }
  .num { align-self: flex-end; margin-right: .1rem; }
  .eline { font-size: .72rem; padding: .1rem .28rem; }
}

.vbody { margin-top: .5rem; padding-top: .5rem; border-top: 1px solid var(--line); }

import { APPS } from './shared/apps.js';

const VERSION = '2026-11-26.10';
const CACHE = `mine-${VERSION}`;

const SHELL = [
  './', './index.html', './app.js', './style.css', './home.css', './manifest.json', './icon.svg',
  './shared/apps.js', './shared/store.js', './shared/github.js', './shared/md.js',
  './shared/markdown.js', './shared/prefs.js', './shared/ui.js', './shared/sync.js',
  './shared/search.js',
  './shared/vendor/js-yaml.mjs', './shared/vendor/rrule.mjs', './shared/vendor/tslib.mjs',
  ...APPS.flatMap(a => [`./${a.slug}/`, `./${a.slug}/icon.svg`,
    ...(a.files || []).map(f => `./${a.slug}/${f}`)])
];

self.addEventListener('install', e => e.waitUntil(
  caches.open(CACHE).then(c => c.addAll(SHELL)).then(() => undefined)
));

self.addEventListener('activate', e => e.waitUntil((async () => {
  for (const k of await caches.keys()) if (k !== CACHE) await caches.delete(k);
  await self.clients.claim();
})()));

// The page asks both workers for their version and only offers the update when they differ:
// a byte-identical worker can sit waiting, and then "a worker is waiting" would mean a banner
// that never goes away.
self.addEventListener('message', e => {
  if (e.data === 'skip-waiting') self.skipWaiting();
  else if (e.data === 'version') e.ports[0]?.postMessage(VERSION);
});

self.addEventListener('fetch', e => {
  const url = new URL(e.request.url);
  // Never cache API traffic: a stale ETag would silently break sync.
  if (url.origin !== location.origin) return;
  if (e.request.method !== 'GET') return;
  e.respondWith((async () => {
    const cached = await caches.match(e.request);
    const network = fetch(e.request).then(r => {
// The chrome every app in Mine builds its screens out of: DOM helpers, the icon set, the
// overlay mechanisms, and the settings row. Its stylesheet is the shared base, ../style.css.
//
// An app imports what it needs from here and adds its own on top - the calendar's icons, its
// state object, its views. Nothing in this file knows about any one app.

export const $ = s => document.querySelector(s);
export const el = (tag, cls, text) => {
  const n = document.createElement(tag);
  if (cls) n.className = cls;
  if (text != null) n.textContent = text;
  return n;
};
export const phone = () => !matchMedia('(min-width: 600px)').matches;

// ---- icons ---------------------------------------------------------------------------------
// Hand-drawn on a 16x16 box. No icon font and no CDN: the CSP allows neither, and an inline
// path cannot fail to load.
//
// What is in here is the vocabulary shared across Mine - the verbs every app needs, and the two
// conventions REQUIREMENTS.md states for all of them: a save is a green disk and a trashcan is a
// red trashcan. A second app drawing its own trashcan path is how that convention would quietly
// stop being one. An app's own subjects - the calendar's recurrence, its stages - are registered
// by that app with addIcons().

// Drawn as outlines rather than solids: a stroked glyph is what carries Mine's paper look, and
// at 1.2-1.4 it stays legible at 16px.
const NS = 'http://www.w3.org/2000/svg';
const ICON = {
  trash:  { d: 'M3 5.2h10M6.4 5.2V3.4h3.2v1.8M4.7 5.2l.5 8.4h5.6l.5-8.4M6.8 7.6v3.4M9.2 7.6v3.4', stroke: 1.3 },
  disk:   { d: 'M3.2 3.2h7.3l2.3 2.4v7.2H3.2zM5.7 3.2v3.3h4V3.2M5.7 9.3h4.6v3.5H5.7', stroke: 1.3 },
  pen:    { d: 'M11.4 2.1l2.5 2.5-7.7 7.7-3.3.8.8-3.3zM9.6 3.9l2.5 2.5', stroke: 1.3 },
  plus:   { d: 'M8 3v10M3 8h10', stroke: 1.8 },
  x:      { d: 'M4 4l8 8M12 4l-8 8', stroke: 1.8 },
  chev:   { d: 'M10 3.5 5.5 8l4.5 4.5', stroke: 1.8 },
  // Three lines of text: a details row, or a markdown body. Every app keeps one.
  lines:  { d: 'M3 4.6h10M3 8h10M3 11.4h6.4', stroke: 1.6 },
  // Three lines of equal length for the hamburger, so `lines` keeps meaning details and no icon
  // means two things.
  menu:   { d: 'M2.4 4.4h11.2M2.4 8h11.2M2.4 11.6h11.2', stroke: 1.6 },
  // A clock face for the logs: the panel's subject is when the last attempt ran and how long the
  // queue has been waiting. A stack of lines would read as details, which `lines` already means.
  logs:   { d: 'M8 2.6a5.4 5.4 0 1 0 0 10.8A5.4 5.4 0 0 0 8 2.6zM8 5.1V8.3l2.5 1.6', stroke: 1.5 },
  // A magnifier for search, which every app opens over its own folder (./search.js).
  search: { d: 'M7.1 2.4a4.7 4.7 0 1 0 0 9.4 4.7 4.7 0 0 0 0-9.4zM10.6 10.6 14 14', stroke: 1.5 },
  house:  { d: 'M2.5 7.3 8 2.5l5.5 4.8V13.5H9.6V9.7H6.4v3.8H2.5z', stroke: 1.4 },
  gear:   { d: 'M8 5.6a2.4 2.4 0 1 0 0 4.8 2.4 2.4 0 0 0 0-4.8zM7.1 1.4h1.8l.3 1.7 1.2.5 1.4-1 1.3 1.3-1 1.4.5 1.2 1.7.3v1.8l-1.7.3-.5 1.2 1 1.4-1.3 1.3-1.4-1-1.2.5-.3 1.7H7.1l-.3-1.7-1.2-.5-1.4 1-1.3-1.3 1-1.4-.5-1.2-1.7-.3V7.1l1.7-.3.5-1.2-1-1.4 1.3-1.3 1.4 1 1.2-.5z', stroke: 1.2 }
};

// An app's own icons, merged in at module load. A name already here is overwritten, which is the
// only way an app could redraw a shared convention - so don't.
export const addIcons = table => Object.assign(ICON, table);

export function icon(name) {
  const spec = ICON[name];
  const svg = document.createElementNS(NS, 'svg');
  svg.setAttribute('viewBox', '0 0 16 16');
  svg.setAttribute('aria-hidden', 'true');
  const p = document.createElementNS(NS, 'path');
  p.setAttribute('d', spec.d);
  if (spec.stroke) {
    p.setAttribute('fill', 'none');
    p.setAttribute('stroke', 'currentColor');
    p.setAttribute('stroke-width', String(spec.stroke));
    p.setAttribute('stroke-linecap', 'round');
    p.setAttribute('stroke-linejoin', 'round');
  } else {
    p.setAttribute('fill', 'currentColor');
  }
  svg.append(p);
  return svg;
}

// `name` is an icon name, or any other string to use as a glyph. An icon row is icons
// throughout; a `24h` or a `!` is a character, because there is no icon for either.
export function iconBtn(name, label, cls = '') {
  const b = el('button', ['ib', cls].filter(Boolean).join(' '));
  b.type = 'button';
  b.title = label;
  b.setAttribute('aria-label', label);
  b.append(ICON[name] ? icon(name) : el('span', 'glyph', name));
  return b;
}

// ---- overlays ------------------------------------------------------------------------------
// Three mechanisms. `openPop` hangs a dropdown off the button that opened it. `openCentred` is a
// panel or a preview, centred by the stylesheet and only unhidden. `openRowPop` is the third and
// the odd one: a field's popup inside a modal, which carries **no scrim**, so the tap that
// dismisses it still reaches the row it landed on and moving from one field to the next is one
// tap rather than two. That is the whole reason it is not one of the other two.
//
// `#scrim` is a convention: an app that opens overlays has one, and the base stylesheet styles
// it. The pops an app closes together are the ones it registers.

let POPS = [];

// Every overlay this app closes with closePops(), as selectors. Called once, at boot.
export const registerPops = selectors => { POPS = selectors; };

export const openCentred = pop => { pop.hidden = false; $('#scrim').hidden = false; };

// Under the thing that opened it, flipped above when there is no room below - a row near the
// foot of a long modal is the case that needs it.
function place(pop, anchor, align) {
  const r = anchor.getBoundingClientRect();
  const w = pop.offsetWidth;
  const h = pop.offsetHeight;
  const left = align === 'right' ? r.right - w : r.left;
  pop.style.left = `${Math.max(8, Math.min(left, innerWidth - w - 8))}px`;
  const below = r.bottom + 6;
  const above = r.top - 6 - h;
  pop.style.top = `${below + h > innerHeight - 8 && above > 8 ? above : below}px`;
}

// The anchors currently reading as expanded, so closePops can put them back without being told
// which buttons an app has.
const expanded = new Set();

export function openPop(pop, anchor, align = 'left') {
  pop.hidden = false;
  $('#scrim').hidden = false;
  place(pop, anchor, align);
  anchor.setAttribute?.('aria-expanded', 'true');
  expanded.add(anchor);
}

export function openRowPop(pop, anchor) {
  pop.hidden = false;
  place(pop, anchor, 'left');
}

export function closePops() {
  for (const id of [...POPS, '#scrim']) {
    const n = $(id);
    if (n) n.hidden = true;
  }
  for (const a of expanded) a.setAttribute?.('aria-expanded', 'false');
  expanded.clear();
}

// ---- settings rows -------------------------------------------------------------------------
// Two halves: the label on the left, its control on the right, so the controls line up in one
// column however long a label is. A unit shares the right half with its control rather than
// dropping below it, which is the one place a row would otherwise go ragged.

export function row(label, control, suffix) {
  const r = el('div', 'srow');
  r.append(el('span', 'slab', label));
  if (!suffix) r.append(control);
  else {
    const v = el('div', 'sval');
    v.append(control, el('span', 'ssuf', suffix));
    r.append(v);
  }
  return r;
}

export function choose(options, current, onChange) {
  const s = el('select');
  for (const [v, text] of options) {
    const o = el('option', '', text);
    o.value = String(v);
    if (String(v) === String(current)) o.selected = true;
    s.append(o);
  }
  s.addEventListener('change', () => onChange(s.value));
  return s;
}

export function toggle(current, onChange) {
  const i = el('input');
  i.type = 'checkbox';
  i.checked = !!current;
  i.addEventListener('change', () => onChange(i.checked));
  return i;
}

export function numberField(current, min, onChange) {
  const i = el('input');
  i.type = 'number';
  i.min = String(min);
  i.value = String(current);
  i.addEventListener('change', () => {
    const n = Number(i.value);
    if (Number.isInteger(n) && n >= min) onChange(n); else i.value = String(current);
  });
  return i;
}

export function dateField(current, onChange) {
  const i = el('input');
  i.type = 'date';
  i.value = current;
  i.addEventListener('change', () => { if (i.value) onChange(i.value); });
  return i;
}
// Theme and date format belong to Mine, not to any one app: the main settings and each app's
// show the same two rows, so both read and write these keys.
import { getKV, setKV } from './store.js';

export const THEMES = ['system', 'light', 'dark', 'coffee', 'neutral'];
export const DATE_FORMATS = ['auto', 'dd.mm.yyyy', 'mm/dd/yy'];

export async function loadPrefs() {
  const [theme, dateFormat] = await Promise.all([getKV('mine.theme'), getKV('mine.dateFormat')]);
  return {
    theme: THEMES.includes(theme) ? theme : 'system',
    dateFormat: DATE_FORMATS.includes(dateFormat) ? dateFormat : 'auto'
  };
}

export const setPref = (key, value) => setKV(`mine.${key}`, value);

// 'system' means leave it to prefers-color-scheme; the attribute is what the stylesheet
// overrides that with. A pinned theme also pins the phone's bar to its page colour; 'system'
// hands the bar back to the two media-keyed tags in the page.
export function applyTheme(theme) {
  const root = document.documentElement;
  const pinned = theme !== 'system' && THEMES.includes(theme);
  if (pinned) root.dataset.theme = theme;
  else delete root.dataset.theme;
  const bg = getComputedStyle(root).getPropertyValue('--bg').trim();
  for (const m of document.querySelectorAll('meta[name="theme-color"]')) {
    m.dataset.own ??= m.content;
    m.content = pinned ? bg : m.dataset.own;
  }
}

// A bare 'YYYY-MM-DD' in the chosen format. 'auto' follows the device's locale. Parsed at
// local noon: a bare date is a calendar date and must not be shifted by a zone.
export function formatDate(key, fmt = 'auto', opts) {
  const [y, m, d] = String(key).split('-');
  if (fmt === 'dd.mm.yyyy') return `${d}.${m}.${y}`;
  if (fmt === 'mm/dd/yy') return `${m}/${d}/${y.slice(2)}`;
  return new Date(`${key}T12:00:00`).toLocaleDateString(undefined,
    opts || { day: 'numeric', month: 'short', year: 'numeric' });
}

export const weekdayName = (key, style = 'long') =>
  new Date(`${key}T12:00:00`).toLocaleDateString(undefined, { weekday: style });

// The same date two characters shorter: a two-digit year, in the chosen format. The entry
// popup's when-row carries two readings on one line - a start and an end - and the short year
// is what buys the room for the second.
export function shortDate(key, fmt = 'auto') {
  const [y, m, d] = String(key).split('-');
  if (fmt === 'dd.mm.yyyy') return `${d}.${m}.${y.slice(2)}`;
  if (fmt === 'mm/dd/yy') return `${m}/${d}/${y.slice(2)}`;
  return new Date(`${key}T12:00:00`).toLocaleDateString(undefined,
    { day: '2-digit', month: '2-digit', year: '2-digit' });
}

// ---- a date as it is typed ------------------------------------------------------------------
// A date typed into a box is read in the order it is read back in, so the format row governs
// both. `auto` asks the locale about a date it cannot misread - 2026-11-19, where 19 can only
// be the day - and takes the order and the separator from the answer.

const FIELDS = { dmy: ['d', 'm', 'y'], mdy: ['m', 'd', 'y'], ymd: ['y', 'm', 'd'] };

export function dateOrder(fmt = 'auto') {
  if (fmt === 'dd.mm.yyyy') return { order: 'dmy', sep: '.' };
  if (fmt === 'mm/dd/yy') return { order: 'mdy', sep: '/' };
  const probe = new Date('2026-11-19T12:00:00').toLocaleDateString(undefined,
    { day: '2-digit', month: '2-digit', year: 'numeric' });
  const parts = probe.split(/\D+/).filter(Boolean);
  const order = parts[0] === '2026' ? 'ymd' : parts[0] === '19' ? 'dmy' : 'mdy';
  return { order, sep: (probe.match(/[.\/-]/) || ['.'])[0] };
}

const pad2 = n => String(n).padStart(2, '0');

export function dateTextOf(key, fmt = 'auto') {
  if (!key) return '';
  const [y, m, d] = String(key).split('-');
  const { order, sep } = dateOrder(fmt);
  return FIELDS[order].map(f => (f === 'y' ? y : f === 'm' ? m : d)).join(sep);
}

export const datePlaceholder = (fmt = 'auto') => {
  const { order, sep } = dateOrder(fmt);
  return FIELDS[order].map(f => (f === 'y' ? 'YYYY' : f === 'm' ? 'MM' : 'DD')).join(sep);
};

// Forgiving in the same way a typed time is: in a day-first format `19.11.2026`, `19.11.26`,
// `19112026`, `191126` and `1911` are all 19 November 2026, the last taking its year from the
// month the picker was showing. Anything that is not a date of the calendar - 31 February, a
// month of 19 where the month comes first - is refused, and the box goes back to the draft.
export function parseDateText(text, fmt = 'auto', ref = '') {
  const t = String(text).trim();
  if (!t) return null;
  const { order } = dateOrder(fmt);
  const names = FIELDS[order];
  let parts = t.split(/\D+/).filter(Boolean);
  if (parts.length === 1) {
    const digits = parts[0];
    if (names[0] === 'y') {
      if (digits.length !== 8) return null;
      parts = [digits.slice(0, 4), digits.slice(4, 6), digits.slice(6)];
    } else {
      if (![4, 6, 8].includes(digits.length)) return null;
      parts = [digits.slice(0, 2), digits.slice(2, 4), digits.slice(4)].filter(Boolean);
    }
  }
  if (parts.length === 2 && names[0] === 'y') return null;
  if (parts.length < 2 || parts.length > 3) return null;
  const got = {};
  names.forEach((n, i) => { got[n] = parts[i] ?? ''; });
  const refYear = String(ref).slice(0, 4) || String(new Date().getFullYear());
  const y = got.y === '' ? Number(refYear)
    : got.y.length <= 2 ? 2000 + Number(got.y) : Number(got.y);
  const m = Number(got.m), d = Number(got.d);
  if (!(y >= 1900 && y <= 2999 && m >= 1 && m <= 12 && d >= 1 && d <= 31)) return null;
  const key = `${y}-${pad2(m)}-${pad2(d)}`;
  // 31 February parses and is not a day, so the answer is checked against the calendar.
  return new Date(`${key}T12:00:00`).getDate() === d ? key : null;
}

// The filter, and the hamburger's two errands, each its own overlay. The filter is a dropdown off
// its own button in the pane, because it is the one you open often and the view it narrows has to
// stay in sight while you narrow it; the settings are the nine rows that change once, so they are a centred panel. One
// panel held both until the two were told apart by a heading alone - which is a weak way to
// separate a thing you open daily from a thing you open twice, and it cost the filter the room
// to show its groups. The logs are a centred panel too; what goes in it is drawn by
// ../shared/sync.js, because the queue it reports on is shared with every other app.
//
// Everything here is stored on the device except the groups, the sprint length and the first
// sprint date: those three are data and live in the repo, because the sprint a task belongs to
// is derived from them and two devices that disagreed would put the same card in different
// sprints. Theme and date format are Mine-wide, not the calendar's.
//
// Every settings row is two halves - the label on the left, its control on the right - so the
// controls line up in one column. The row and its four controls are in ../shared/ui.js. The
// groups are behind a button rather than listed, because a list grew with the repo and pushed
// the nine settings that never change below the fold.
import { setKV } from '../shared/store.js';
import { renderLogs } from '../shared/sync.js';
import { STAGES, saveSettings, setZone, getZone } from './data.js';
import { THEMES, DATE_FORMATS, applyTheme, setPref } from '../shared/prefs.js';
import { openGroups } from './popup.js';
import {
  S, $, el, icon, closePops, openPop, openRowPop, openCentred, colorOf, labelOf, STAGE_COLOR, STAGE_LABEL,
  row, choose, toggle, numberField, dateField
} from './ui.js';

export function openFilter() {
  if (!$('#filter-pop').hidden) return closePops();
  closePops();
  renderFilter();
  openPop($('#filter-pop'), $('#filter-btn'), 'right');
}

export function openPanel() {
  closePops();
  build();
  openCentred($('#settings-panel'));
}

export function openLogs() {
  closePops();
  openCentred($('#logs-panel'));
  renderLogs($('#logs-body'), S.sync);
}

// ---- the filter ----------------------------------------------------------------------------
// A view filter, remembered per device. Groups are named and coloured in the settings panel's
// `edit groups`, not here.

function groupNames() {
  const names = new Set(Object.keys(S.model.groups));
  let ungrouped = false;
  for (const e of [...S.model.dated, ...S.model.rules]) {
    if (e.data.group) names.add(e.data.group); else ungrouped = true;
  }
  const out = [...names].sort().map(n => [n, labelOf(n)]);
  if (ungrouped) out.push(['', 'no group']);
  return out;
}

// The categories and the stages each open a list of their own off a row, so that a repo with
// twenty groups does not make a twenty-row dropdown of the filter. A row's icon is lit while its list
// has something switched off, which is all that says so with the list shut.

function groupRows() {
  return groupNames().map(([name, label]) => {
    const lab = el('label', 'glab grp');
    const box = el('input');
    box.type = 'checkbox';
    box.checked = !S.hidden.has(name);
    box.addEventListener('change', async () => {
      if (box.checked) S.hidden.delete(name); else S.hidden.add(name);
      await setKV('calendar.hiddenGroups', [...S.hidden]);
      S.render();
    });
    const sw = el('span', 'swatch');
    sw.style.background = colorOf(name);
    lab.append(box, sw, el('span', '', label || name));
    return lab;
  });
}

function stageRows() {
  return STAGES.map(stage => {
    const lab = el('label', 'glab stg');
    const box = el('input');
    box.type = 'checkbox';
    box.checked = !S.hiddenStages.has(stage);
    box.addEventListener('change', async () => {
      if (box.checked) S.hiddenStages.delete(stage); else S.hiddenStages.add(stage);
      await setKV('calendar.hiddenStages', [...S.hiddenStages]);
      S.render();
    });
    const sw = el('span', 'swatch');
    sw.style.background = STAGE_COLOR[stage];
    lab.append(box, sw, el('span', '', STAGE_LABEL[stage]));
    return lab;
  });
}

const LISTS = {
  group: { ic: 'ball', title: 'Category', rows: groupRows, hidden: () => S.hidden },
  stage: { ic: 'tick', title: 'Stage', rows: stageRows, hidden: () => S.hiddenStages }
};
let shown = 'group';   // which of the two #filter-sub holds

function renderList() {
  $('#filter-sub-title').textContent = LISTS[shown].title;
  $('#filter-sub-body').replaceChildren(...LISTS[shown].rows());
}

// No scrim of its own: the filter's is already up, and a tap on it closes both.
function toggleList(key) {
  const pop = $('#filter-sub');
  const shut = !pop.hidden && shown === key;
  pop.hidden = true;
  if (shut) return;
  shown = key;
  renderList();
  openRowPop(pop, $(`#filter-body [data-list="${key}"]`));
}

function listBtn(key) {
  const { ic, title, hidden } = LISTS[key];
  const b = el('button', hidden().size ? 'mrow on' : 'mrow');
  b.type = 'button';
  b.dataset.list = key;
  b.append(icon(ic), el('span', '', title));
  b.addEventListener('click', () => toggleList(key));
  return b;
}

export function renderFilter() {
  // The stages and importance narrow **every** view, not only the board: a month with the done
// editable parts against the baseline taken when the popup opened. One comparison, so the disk
// cannot appear where the prompt would stay silent.
const snapshot = d => JSON.stringify([d.type, d.stage, d.important, d.title,
  d.allDay, d.startDate, d.startTime, d.endDate, d.endTime, d.v]);

// A new entry always has something to write, there being no file yet; the disk is disabled until
// it has a title instead.
const dirty = () => !!D && (!D.occ || snapshot(D) !== D.clean);

// ---- leaving -------------------------------------------------------------------------------

// Leaving a popup that holds unsaved changes asks first - the x, the backdrop and Escape are one
// way out and ask one question. A row's own x is not guarded and has nothing to guard: it closes
// a row and keeps what is in it.
function closePopup() {
  if (D && S.prefs.confirmDiscard && snapshot(D) !== D.clean) {
    $('#ask-never').checked = false;
    $('#ask').hidden = false;
    return;
  }
  discard();
}

function discard() {
  $('#ask').hidden = true;
  $('#popup').hidden = true;
  $('#fpop').hidden = true;
  active = null;
  popped = null;
  flow = null;
  D = null;
}

// Escape unwinds the one layer there is: a field's popup, which is a real overlay with an x of
// its own, swallows it so that Escape inside a field does not throw away the edit the field is
// part of. An **inline row does not** - it is the row in its editing state, not a layer over
// anything, and leaving it loses nothing, so Escape there keeps meaning "leave the popup". A new
// entry opens with its title row already an input, and making that swallow the first Escape would
// have cost two presses to leave the commonest popup in the app.
export function escapeEntry() {
  if (popped !== null) closeFieldPop();
  else closePopup();
}

$('#ask-keep').addEventListener('click', () => { $('#ask').hidden = true; });
$('#ask').addEventListener('click', e => { if (e.target === $('#ask')) $('#ask').hidden = true; });
$('#ask-discard').addEventListener('click', async () => {
  // Ticking it silences the prompt on this device for good; the panel's settings row is what
  // puts it back, because nothing in Mine may be switched off from a place that cannot switch
  // it back on.
  if ($('#ask-never').checked) {
    S.prefs.confirmDiscard = false;
    await setKV('calendar.confirmDiscard', false);
  }
  discard();
});

$('#popup').addEventListener('click', e => {
  if (justClosed === null && e.target === $('#popup')) closePopup();
});

// The shell: the top pane, navigation, the date picker, the zoom, the hamburger's menu, the sync
// line, and which view the big calendar window holds.
import { getConfig, getKV, setKV } from '../shared/store.js';
import { createSync } from '../shared/sync.js';
import {
  loadModel, todayKey, addDays, addMonths, partsOf, weekStartOf, isoWeek, setZone,
  sprintRange, sprintOf, occurrences
} from './data.js';
import {
  S, $, el, phone, dayLabel, icon, monthDays, currentSprint, openPop, closePops, registerPops
} from './ui.js';
import { renderView, wireView, openDayPop } from './views.js';
import { renderKanban } from './kanban.js';
import { escapeEntry, openEntry } from './popup.js';
import { openFilter, openPanel, openLogs, renderFilter, renderFilterCount } from './settings.js';
import { loadPrefs, applyTheme, weekdayName } from '../shared/prefs.js';
import { openSearch, refreshSearch } from '../shared/search.js';
import { draggable } from './drag.js';

let pick = { mode: 'days', y: 2026, m: 0, base: 0 };

// ---- rendering -----------------------------------------------------------------------------

function render() {
  const k = S.view.mode === 'K';
  $('#period-label').textContent = periodLabel();

  // One slot carries the way to the other kind of view. The board is not a zoom step, which is
  // why it has a slot of its own rather than a place in the cycle the label walks.
  $('#board').replaceChildren(icon(k ? 'cal' : 'board'));
  $('#board').setAttribute('aria-label', k ? 'Back to the month view' : 'Kanban');
  $('#period').setAttribute('aria-label', k ? 'Pick a sprint' : 'Pick a date');

  if (k) renderKanban($('#view'));
  else renderView($('#view'));
  renderZoom();
  renderFilter();
  renderFilterCount();
  refreshSearch();
}

// The pane has to fit a phone, so every label is short. The month name is the device locale's
// abbreviation, upper-cased - short beats English.
const shortMonth = key => new Date(`${key}T12:00:00`)
  .toLocaleDateString(undefined, { month: 'short' }).replace(/\./g, '').toUpperCase();

function periodLabel() {
  const { mode, anchor } = S.view;
  const [y, , d] = partsOf(anchor);
  if (mode === 'D')
    return `${weekdayName(anchor, 'short').slice(0, 2).toUpperCase()} ${d}/${shortMonth(anchor)}`;
  if (mode === 'W') {
    // The ISO number is in the label whether or not the gutter is on, and the month is the one
    // the row's fourth day is in - the rule the gutter uses, so the two cannot disagree.
    const a = weekStartOf(anchor, S.prefs.weekStart);
    return `W${isoWeek(addDays(a, 3))}/${shortMonth(addDays(a, 3))}`;
  }
  if (mode === 'M') return `${shortMonth(anchor)}/${String(y).slice(2)}`;
  if (mode === 'Y') return String(y);
  return String(S.view.sprint);
}

// ---- the zoom ------------------------------------------------------------------------------
// A button beside the view switch, reading the view it is in and offering what the view it was opened in can do and nothing
// else: the four periods in a calendar view, the board's two orientations on the board. It
// replaces the label's old cycle, which asked up to three taps to reach a view and never said
// which one you were in.

const PERIODS = [['D', 'day'], ['W', 'week'], ['M', 'month'], ['Y', 'year']];
const ORIENTS = [['vert', 'vertical'], ['horz', 'horizontal']];

function renderZoom() {
  const board = S.view.mode === 'K';
  const btn = $('#zoom-btn');
  btn.replaceChildren(board ? icon(S.prefs.boardOrientation === 'vert' ? 'vert' : 'horz')
    : el('span', 'glyph', S.view.mode));
  btn.setAttribute('aria-label', board
    ? `Zoom: ${S.prefs.boardOrientation === 'vert' ? 'vertical' : 'horizontal'}`
    : `Zoom: ${PERIODS.find(([v]) => v === S.view.mode)[1]}`);
  const rows = board
    ? ORIENTS.map(([v, text]) => [v, text, S.prefs.boardOrientation === v, setOrientation])
    : PERIODS.map(([v, text]) => [v, text, S.view.mode === v, setMode]);
  $('#zoom-body').replaceChildren(...rows.map(([v, text, on, pick]) => {
    const b = el('button', `zrow${on ? ' on' : ''}`);
    b.type = 'button';
    b.setAttribute('aria-pressed', String(on));
    b.append(el('span', 'dot'), el('span', '', text));
    b.addEventListener('click', () => pick(v));
    return b;
  }));
}

function setMode(mode) {
  S.view.mode = mode;
  closePops();
  render();
}

// Remembered per device: it is a preference about this screen, like confirm discard. The
// calendar's own zoom is not - the app opens on the month, on today, as it always has.
async function setOrientation(v) {
  S.prefs.boardOrientation = v;
  await setKV('calendar.boardOrientation', v);
  S.view.col = 0;
  closePops();
  render();
}

$('#zoom-btn').addEventListener('click', () => {
  if (!$('#zoom-pop').hidden) return closePops();
  closePops();
  renderZoom();
  openPop($('#zoom-pop'), $('#zoom-btn'));
});

// ---- navigation ----------------------------------------------------------------------------

$('#board').addEventListener('click', () => {
  if (S.view.mode === 'K') S.view.mode = 'M';
  else {

  // The stages and importance narrow **every** view, not only the board: a month with the done
  // ones out of it is as much a thing to want as a board of them, and importance is on an event
  // now. All of it is remembered per device - a filter that empties a month is one you want to
  // find still on after a reload, and the filter button's count says it is.
  const kids = [...Object.keys(LISTS).map(listBtn), el('div', 'fsep')];

  const imp = el('label', 'glab imp');
  const impBox = el('input');
  impBox.type = 'checkbox';
  impBox.checked = S.kfilter.importantOnly;
  impBox.addEventListener('change', async () => {
    S.kfilter.importantOnly = impBox.checked;
    await setKV('calendar.importantOnly', impBox.checked);
    S.render();
  });
  imp.append(impBox, el('span', 'glyph', '!'), el('span', '', 'important only'));
  kids.push(imp);

  // The assignee stays the board's own: a card is the one place a name is read off an entry.
  if (S.view.mode === 'K') {
    const people = [...new Set([...S.model.dated, ...S.model.rules]
      .flatMap(e => [].concat(e.data.participants ?? []).map(String)))].sort();
    kids.push(row('Assignee', choose([['', 'anyone'], ...people.map(p => [p, p])],
      S.kfilter.assignee, v => { S.kfilter.assignee = v; S.render(); })));
  }

  $('#filter-body').replaceChildren(...kids);
  renderList();
  renderFilterCount();
}

// A filter that is on says so on the filter's own button, which otherwise looks the same
// whatever it is doing. The count is **one per kind of narrowing** - the
// groups, the stages, importance, the assignee - rather than one per switched-off thing: a repo
// with twenty groups and fifteen hidden would read 16, which is a true number nobody can act
// on, where 4 says there are four things to look at in the one place that lists them.
export function filterCount() {
  return (S.hidden.size ? 1 : 0) + (S.hiddenStages.size ? 1 : 0)
    + (S.kfilter.importantOnly ? 1 : 0) + (S.kfilter.assignee ? 1 : 0);
}

export function renderFilterCount() {
  const n = filterCount();
  $('#filter-btn').querySelector('.fcount')?.remove();
  $('#filter-btn').setAttribute('aria-label',
    n ? `Filter — ${n} filter${n > 1 ? 's' : ''} on` : 'Filter');
  if (n) $('#filter-btn').append(el('span', 'fcount', String(n)));
}

// Nine rows and nothing after them: there is no paragraph explaining what is stored where,
// because that belongs in REQUIREMENTS.md and not on a panel opened to change the theme.
function build() {
  $('#settings-body').replaceChildren(
    row('Groups', groupsButton()),
    row('Start week on', choose([[1, 'Monday'], [0, 'Sunday']], S.prefs.weekStart,
      v => local('weekStart', Number(v)))),
    row('Time zone', zoneField()),
    row('Date format', choose(DATE_FORMATS.map(f => [f, f]), S.prefs.dateFormat,
      v => mine('dateFormat', v))),
    row('Calendar weeks', toggle(S.prefs.showWeeks, v => local('showWeeks', v))),
    // The way back on. A prompt silenced from inside itself needs a row that can restore it,
    // because nothing in Mine may be switched off from a place that cannot switch it back on.
    row('Confirm discard', toggle(S.prefs.confirmDiscard, v => local('confirmDiscard', v))),
    row('Sprint length', numberField(S.model.settings.interval, 1,
      v => sprints({ interval: v })), 'weeks'),
    row('First sprint', dateField(S.model.settings.anchor, v => sprints({ anchor: v }))),
    row('Theme', choose(THEMES.map(t => [t, t]), S.prefs.theme, v => mine('theme', v)))
  );
}

// ---- rows ----------------------------------------------------------------------------------
// `row` and its four controls come from ../shared/ui.js. The two below are the calendar's own:
// one opens a popup, the other validates a zone name.

// The same popup the entry popup's category field opens, in its manage-only form: one place
// where a group is named or coloured, so there is no second list to keep in step.
function groupsButton() {
  const b = el('button', 'link', 'edit groups');
  b.type = 'button';
  b.id = 'edit-groups';
  b.addEventListener('click', openGroups);
  return b;
}

// A zone name, not an offset: a plain UTC+1 is an hour wrong for half the year in any zone with
// daylight saving. Empty means the device's own.
function zoneField() {
  const i = el('input');
  i.value = S.prefs.timeZone;
  i.placeholder = getZone();
  i.autocapitalize = 'off';
  i.spellcheck = false;
  i.addEventListener('change', () => {
    const typed = i.value.trim();
    const chosen = setZone(typed);
    if (typed && chosen !== typed) {
      i.value = '';
      S.status(`"${typed}" is not a zone name — using ${chosen}.`, true);
    }
    local('timeZone', i.value.trim());
    i.placeholder = getZone();
  });
  return i;
}

// ---- writes --------------------------------------------------------------------------------

async function sprints(patch) {
  await saveSettings({ ...S.model.settings, ...patch });
  S.model = await S.reload();
  build();
  S.render();
  S.push('calendar: sprint settings');
}

async function local(key, value) {
  S.prefs[key] = value;
  await setKV(`calendar.${key}`, value);
  S.render();
}

// A re-render redraws the filter, because the board's two controls are only in it on the board.
// `S.render()` calls back into renderFilter, so this file does not have to.

async function mine(key, value) {
  S.prefs[key] = value;
  await setPref(key, value);
  if (key === 'theme') applyTheme(value);
  S.render();
}
  else {
    S.view.mode = 'K';
    S.view.sprint = sprintOf(S.view.anchor, S.model.settings) || currentSprint();
  }
  closePops();
  render();
});

function step(dir) {
  const v = S.view;
  if (v.mode === 'D') v.anchor = addDays(v.anchor, dir);
  else if (v.mode === 'W') v.anchor = addDays(v.anchor, 7 * dir);
  else if (v.mode === 'M') v.anchor = addMonths(v.anchor, dir);
  else if (v.mode === 'Y') v.anchor = addMonths(v.anchor, 12 * dir);
  else v.sprint = Math.max(1, v.sprint + dir);
  closePops();
  render();
}
$('#prev').addEventListener('click', () => step(-1));
$('#next').addEventListener('click', () => step(1));

// There is no jump-to-today button and no `+` in the pane: today is the highlighted day in the
// dropdown, and an entry is created where it will live - a cell, the day preview, or a kanban
// column header.

for (const [id, name] of [['#home', 'house'], ['#search-btn', 'search'], ['#filter-btn', 'filter'],
  ['#menu-btn', 'menu'],
  ['#day-add', 'plus'], ['#day-close', 'x'], ['#sub-close', 'x'], ['#settings-close', 'x'],
  ['#filter-close', 'x'], ['#filter-sub-close', 'x'], ['#fpop-close', 'x'], ['#logs-close', 'x']])
  $(id).append(icon(name));

// ---- search --------------------------------------------------------------------------------
// The search is Mine's, in ../shared/search.js; what the calendar tells it is its folder, which
// keys hold the title and the date, and what opening a result is. A file without a title is not
// an entry - groups.md, settings.md and an override recording only what it changed - so a
// repeating entry is one result, its rule file.

$('#search-btn').addEventListener('click', () => openSearch({
  folder: 'calendar/', title: 'title', date: 'start', fields: ['group', 'participants', 'location'],
  open: openFound
}));

// A dated entry opens as itself. A repeating one opens on its next occurrence from today, or on
// its last if the series is over.
function openFound(path) {
  const today = todayKey();
  const rule = S.model.rules.find(r => r.path === path);
  if (rule) {
    const mine = (from, to) => occurrences(S.model, from, to).filter(o => o.seriesPath === path);
    const start = String(rule.data.start).slice(0, 10);
    const next = mine(today, addDays(today, 3660)).find(o => o.dayKey >= today);
    return openEntry(next || mine(start < today ? start : today, today).pop());
  }
  const e = S.model.dated.find(d => d.path === path)
    || [...S.model.overrides.values()].find(d => d.path === path);
  if (!e) return;
  const day = String(e.data.start ?? e.data['recurrence-id']).slice(0, 10);
  openEntry(occurrences(S.model, addDays(day, -1), addDays(day, 1)).find(o => o.path === path));
}

// ---- the filter, and the hamburger's menu --------------------------------------------------
// The filter has a button of its own in the pane: it is opened daily, and a menu in front of it
// was a tap spent naming the one errand you came for. The hamburger keeps the two you open
// rarely, each named before it is opened - the settings, and the logs, which you reach for when
// the sync line says something you did not expect.
const MENU = [['gear', 'settings', openPanel], ['logs', 'logs', openLogs]];

function openMenu() {
  if (!$('#menu-pop').hidden) return closePops();
  closePops();
  $('#menu-body').replaceChildren(...MENU.map(([ic, text, open]) => {
    const b = el('button', 'mrow');
    b.type = 'button';
    b.append(icon(ic), el('span', '', text));
    b.addEventListener('click', open);   // each one closes the menu on its way in
    return b;
  }));
  openPop($('#menu-pop'), $('#menu-btn'), 'right');
}

$('#menu-btn').addEventListener('click', openMenu);
$('#filter-btn').addEventListener('click', openFilter);
$('#filter-close').addEventListener('click', closePops);
// The one `x` that leaves what is under it open.
$('#filter-sub-close').addEventListener('click', () => { $('#filter-sub').hidden = true; });
$('#settings-close').addEventListener('click', closePops);
$('#logs-close').addEventListener('click', closePops);

// The sync line is the thing you are looking at when you want to know why, so it is the way in
// as well as the report. Reaching the panel through the hamburger only helps once you know it
// is there.
$('#sync').addEventListener('click', openLogs);

// ---- the dropdown date picker --------------------------------------------------------------
// A month at a time, a 9-year grid, or - in the kanban - a list of sprints.

// The label opens the picker, and that is all it does, in every view and on both platforms. The
// caret existed only because the label's own tap was taken by the zoom; the zoom is a button of
// its own now, so the label is free to be the one thing it was always read as.
function openPicker() {
  if (!$('#picker').hidden) return closePops();
  closePops();
