// A word matches where a word in the text begins with it: `dent` finds "dentist".
const wordRe = w => new RegExp(`(^|[^\\p{L}\\p{N}])${esc(w)}`, 'u');

const fileName = path => path.split('/').pop().replace(/\.md$/, '');
const pathDate = path => (path.match(/\d{4}-\d{2}-\d{2}/) || [''])[0];
const asText = v => Array.isArray(v) ? v.map(String).join(' ') : v == null ? '' : String(v);

// A bare date stays itself; an instant is read on this device's clock.
function dayOf(v) {
  const s = String(v ?? '');
  if (!s.includes('T')) return /^\d{4}-\d{2}-\d{2}/.test(s) ? s.slice(0, 10) : '';
  const d = new Date(s);
  if (isNaN(d)) return s.slice(0, 10);
  const p = n => String(n).padStart(2, '0');
  return `${d.getFullYear()}-${p(d.getMonth() + 1)}-${p(d.getDate())}`;
}

// Each file as what search reads of it. Pure, so the unit checks run it in node.
export function index(files, { folder, title, date, fields = [] }) {
  const out = [];
  for (const f of files) {
    if (!f.path.startsWith(folder) || !f.path.endsWith('.md') || f.text == null) continue;
    const { data, body } = parse(f.text);
    if (data.conflictOf) continue;
    if (title && (data[title] == null || data[title] === '')) continue;
    const head = (body.match(/^#{1,6}[ \t]+(.+)$/m) || [])[1];
    const t = title ? String(data[title]) : (head ? plain(head).trim() : fileName(f.path));
    const text = plain(body);
    out.push({
      path: f.path, title: t, date: date ? dayOf(data[date]) : pathDate(f.path), text,
      fTitle: fold(t), fBody: fold([text, ...fields.map(k => asText(data[k]))].join('\n'))
    });
  }
  return out;
}

// Every word somewhere; a document whose title holds them all first; then the nearest date,
// what is coming before what has been, and an undated document last.
export function find(docs, query, today) {
  const ws = words(query);
  if (!ws.length) return [];
  const res = ws.map(wordRe);
  const hits = [];
  for (const d of docs) {
    if (!res.every(r => r.test(d.fTitle) || r.test(d.fBody))) continue;
    hits.push({ doc: d, tier: res.every(r => r.test(d.fTitle)) ? 0 : 1 });
  }
  const rank = d => !d.date ? [2, ''] : d.date >= today ? [0, d.date] : [1, d.date];
  return hits.sort((a, b) => {
    if (a.tier !== b.tier) return a.tier - b.tier;
    const [ga, ka] = rank(a.doc), [gb, kb] = rank(b.doc);
    if (ga !== gb) return ga - gb;
    if (ka !== kb) return (ga === 0 ? ka < kb : ka > kb) ? -1 : 1;
    return a.doc.title.localeCompare(b.doc.title);
  }).map(h => h.doc);
}

// tree, named from the UTC components of `start` so the name mirrors the stored string.
export function pathFor(data, id = rand4()) {
  if (data.recurrence) return `${ROOT}/recurring/${slug(data.title)}-${id}.md`;
  const s = String(data.start ?? data['recurrence-id'] ?? '');
  if (isAllDay(s)) {
    const [y, m, d] = s.slice(0, 10).split('-');
    return `${ROOT}/${y}/${m}/${y}-${m}-${d}-0000-${id}.md`;
  }
  const t = new Date(s);
  const y = t.getUTCFullYear(), m = pad(t.getUTCMonth() + 1), d = pad(t.getUTCDate());
  return `${ROOT}/${y}/${m}/${y}-${m}-${d}-${pad(t.getUTCHours())}${pad(t.getUTCMinutes())}-${id}.md`;
}

// The 4 random characters, so a move keeps the entry's identity.
export const idTail = path => path.replace(/\.md$/, '').split('-').pop();

// RFC 5545 naming, ordered as the samples are. serialize() drops empty keys rather than
// writing `None`, which a parser would hand back as the string "None".
const ORDER = ['series', 'recurrence-id', 'title', 'type', 'start', 'end', 'stage', 'important',
  'group', 'location', 'recurrence', 'exdate', 'rdate', 'alerts', 'participants', 'status'];

function order(data) {
  const out = {};
  for (const k of ORDER) if (data[k] !== undefined) out[k] = data[k];
  for (const k of Object.keys(data)) if (!ORDER.includes(k)) out[k] = data[k];
  return out;
}

// Pure: what a write would put in the repo. Used by the write path and by the round-trip test.
export const entryFile = (data, body, path) =>
  ({ path: path || pathFor(data), text: serialize(order(data), body || '') });

// ---- writes -----------------------------------------------------------------------------
// These only touch the local mirror and the queue. The push is drain() in app.js, run in the
// background so saving never waits on the network - and one drain is still one commit, so a
// move (delete plus create, because the date is in the path) cannot be half applied.

export async function createEntry(data, body) {
  const f = entryFile(data, body);
  await write(f.path, f.text);
  return f.path;
}

// Moves the file when `start` or `recurrence` changed where it belongs. Overrides pass
// move:false - their path legitimately disagrees with their start and nothing may move them.
export async function updateEntry(path, data, body, { move = true } = {}) {
  let target = move ? pathFor(data, idTail(path)) : path;
  // A rule file's name is permanent: override files reference it through `series`, so
  // retitling must not rename it. Only gaining or losing the rule moves it.
  if (path.startsWith(`${ROOT}/recurring/`) && target.startsWith(`${ROOT}/recurring/`)) target = path;
  const f = entryFile(data, body, target);
  if (target !== path) await remove(path);
  await write(f.path, f.text);
  return f.path;
}

export const deleteEntry = path => remove(path);

// ---- occurrences of a series ------------------------------------------------------------

// A plain skip, where there is nothing to record: exdate on the rule file. An override for the

// Which screen made the attempt, read when it is written rather than when this module loads:
// an app's data module imports this file and the node unit checks import that, where there is
// no `location` at all.
//
// The last path segment that is not a file is the app's folder, which is its slug - so an app
// added tomorrow names itself here without this line being touched. The root app has no such
// segment and is `mine`.
const appName = () => {
  const parts = (globalThis.location?.pathname ?? '').split('/').filter(p => p && !p.includes('.'));
  return APPS.some(a => a.slug === parts.at(-1)) ? parts.at(-1) : 'mine';
};

async function record(op, outcome, status, detail) {
  const app = appName();
  const prev = await getKV('sync.last');
  const now = Date.now();
  const same = prev && prev.op === op && prev.outcome === outcome && prev.status === status;
  await setKV('sync.last', same
    ? { ...prev, lastAt: now, count: prev.count + 1, app, detail }
    : { at: now, lastAt: now, count: 1, app, op, outcome, status: status ?? null, detail });
}

export const lastSync = () => getKV('sync.last');

export async function testConnection(config) {
  const repo = await ok(await rest(`/repos/${config.owner}/${config.repo}`, { config }), 'repo read');
  return { name: repo.full_name, private: repo.private, empty: repo.size === 0 };
}

// ---- pull: 304-guarded, fetches only what changed ----
// Also the first mirror: with no stored ETag it fetches the tree and every blob in it.
//
// The whole repo, always, and deliberately no way to ask for one app's folder. There is a
// single `commitEtag` for the whole mirror, so a pull that fetched only `diary/` would store
// the ETag of a commit it had not mirrored, and the calendar's next pull would 304 against it
// and never see its own files again. A per-folder pull would need a per-folder ETag, and the
// request it saves is one conditional GET.

export async function pull() {
  try {
    const r = await pullNow();
    if (!r.unchanged)
      await record('pull', 'ok', null, r.empty ? 'repo is empty' : `${r.changed} file(s) updated`);
    return r;
  } catch (err) {
    await record('pull', 'failed', err.status ?? null, err.message);
    throw err;
  }
}

async function pullNow() {
  const c = await auth();
  const etag = await getKV('commitEtag');
  const r = await rest(`/repos/${c.owner}/${c.repo}/commits/${c.branch}`,
    { config: c, headers: etag ? { 'If-None-Match': etag } : {} });
  if (r.status === 304) return { changed: 0, unchanged: true };
  if (r.status === 409) return { changed: 0, empty: true };
  await ok(r, 'commit check');
  await setKV('commitEtag', r.headers.get('ETag'));

  const tree = await ok(await rest(
    `/repos/${c.owner}/${c.repo}/git/trees/${c.branch}?recursive=1`, { config: c }), 'tree read');
  if (tree.truncated) throw new SyncError('Tree listing truncated - repo too large for a flat pull.');

  const remote = new Map(tree.tree
    .filter(t => t.type === 'blob' && t.path.endsWith('.md'))
    .map(t => [t.path, t.sha]));
  const local = new Map((await allFiles()).map(f => [f.path, f.oid]));

  let changed = 0;
  for (const [path, sha] of remote) {
    if (local.get(path) === sha) continue;
    const blob = await ok(await rest(`/repos/${c.owner}/${c.repo}/git/blobs/${sha}`, { config: c }), 'blob read');
    await putFile({ path, text: decode(blob.content), oid: sha });
    changed++;
  }
  for (const path of local.keys()) if (!remote.has(path)) { await delFile(path); changed++; }
  return { changed };
}

